"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[813],{813:(e,t,a)=>{a.d(t,{I:()=>i});let s="https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&q=80&w=2000",o="https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&q=80&w=2000",n="https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&q=80&w=2000",i=[{id:"1",slug:"app-scraping",title:"Phone apps, read and saved",client:"Client work",category:"Phone scraping",overview:"Four screen recordings of scripts that open a real Android app, move through it, and save what is on the screen. Store addresses, on-screen text, and level images.",mainImage:"/proofs/posters/app-scraping.jpg",heroImage:"/proofs/posters/app-scraping.jpg",intro:"These are recordings of jobs that ran. A script opens the app on a phone or emulator, finds the screen it needs, reads the text or saves the image, and moves on. The source is the public screen of the app.",challenge:"The data lived inside an app, not on a page you can download. Someone had to open it, scroll, tap, and copy. Doing that by hand for every store, every level, or every screen does not scale, and a person misses rows.",solution:"The runs you can play below drive the app themselves. One finds a store result and reads the address off the screen. One walks an app and pulls the text back from each view. One saves a game’s level images into folders, one level at a time. A later recording shows the same kind of run watched live while it works. Nothing here is a private account or a password. If it is not on the screen a person could already open, it is not collected.",process:{timeline:"Delivered, then recorded",steps:[{title:"Open the real app",description:"The script starts the Android app the client already uses, on a device or an emulator."},{title:"Find the screen",description:"It looks for the view that holds the address, the label, or the image, then waits until that view is actually there."},{title:"Read or save",description:"Text comes back as data. Images are written into folders the client can open."},{title:"Keep going",description:"The next store, the next level, the next screen. The recording is the proof the loop ran."}]},stats:[{label:"Recordings",value:"4",description:"Store text, app screens, level images, and a live run"},{label:"Source",value:"The screen",description:"Public app UI only"},{label:"Output",value:"Files",description:"Text read back, images saved in folders"}],contentImages:[s,n],videos:[{src:"/proofs/app-scraping.webm",poster:"/proofs/posters/app-scraping.jpg",title:"A store address, read off the app",caption:"The script searches inside the app, finds the result, and reads the street address on the screen. You can see the address come back in the log next to the map."},{src:"/proofs/app-scraping-new.webm",poster:"/proofs/posters/app-scraping-new.jpg",title:"The same kind of run, watched live",caption:"A later build. The phone session is on screen while the script taps through and reports each element it finds."},{src:"/proofs/app-scraping-2023.webm",poster:"/proofs/posters/app-scraping-2023.jpg",title:"Walking an Android app, screen by screen",caption:"The runner opens the app, posts each view it lands on, and reads the text. This is the unglamorous part: it keeps going until the screens are done."},{src:"/proofs/app-img-scraping.mp4",poster:"/proofs/posters/app-img-scraping.jpg",title:"Level images, saved as it plays",caption:"A game app on an emulator. As the script moves through levels, each screen’s images land in their own folder. The file window is the delivery."}]},{id:"2",slug:"website-scraping",title:"Menus and product images from public sites",client:"Client work",category:"Website scraping",overview:"Two recordings. One pulls a public restaurant menu into structured rows. One saves product images from a catalog, file by file.",mainImage:"/proofs/posters/web-scraping.jpg",heroImage:"/proofs/posters/web-scraping.jpg",intro:"Both recordings are the job running, not a mockup. One walks a public restaurant site and writes each item as data. The other saves the images from a public product catalog onto disk.",challenge:"A menu or a catalog changes, and the client needs it as rows and files, not as a webpage someone has to reread. Copying it by hand is slow, and the names, prices, and images drift out of date.",solution:"The menu run writes what the page actually shows: currency, market, store, date, and the product name. The image run saves each product picture into a folder as it goes. The sites are public. The feed is only as fresh as the last run, which is why it is built to run again.",process:{timeline:"Recorded on delivery",steps:[{title:"Open the public page",description:"The script loads the site a customer could already visit."},{title:"Take the fields that matter",description:"Store, product, date, currency. Not the whole page, just the row the client asked for."},{title:"Save the pictures",description:"On the catalog job, each product image is written to disk with the rest of the run."},{title:"Leave a file",description:"The client gets rows and images they can open, not a login to someone else’s tool."}]},stats:[{label:"Recordings",value:"2",description:"A menu feed and a product-image run"},{label:"Source",value:"Public sites",description:"Pages a customer can already open"},{label:"Output",value:"Rows + images",description:"Structured fields, pictures on disk"}],contentImages:[n,s],videos:[{src:"/proofs/web-scraping.webm",poster:"/proofs/posters/web-scraping.jpg",title:"A public menu, turned into rows",caption:"Germany, a restaurant site, one product at a time. The log shows currency, market, store name, date, and the product. That is the file the client keeps."},{src:"/proofs/web-img-scraping.mp4",poster:"/proofs/posters/web-img-scraping.jpg",title:"Product images, saved as the run goes",caption:"A public catalog. The script moves through the variants and writes each image into the output folder. The empty folder at the start is the point: you watch it fill."}]},{id:"3",slug:"ewallet-automation",title:"An e-wallet app, driven through its steps",client:"Client work",category:"Custom software",overview:"A screen recording of an e-wallet app being operated by a script, watched live. The taps happen without someone sitting on the phone.",mainImage:"/proofs/posters/ewallet-automation.jpg",heroImage:"/proofs/posters/ewallet-automation.jpg",intro:"The recording is a remote view of the phone while a script drives an e-wallet app. You see the session, the controls, and the run in progress. This is custom software: the app already existed, and the job was to make a repeatable path through it.",challenge:"Wallet flows are long. Open, confirm, move, confirm again. A person can do it once. Doing it the same way every time, and being able to show that it happened, is the actual work.",solution:"The script takes the path through the app and the session is recorded so the client can see the steps, not just a green checkmark in a log. If a screen is missing, the run stops where a person would stop. It does not guess a password or reach into an account the client cannot already open.",process:{timeline:"One recorded delivery",steps:[{title:"The path",description:"Wrote down the taps the app expects, in the order a person already uses."},{title:"Drive the phone",description:"The script performs those taps on the live app."},{title:"Watch it",description:"The session stays on screen so the client can see the wallet move, not only a log line."},{title:"Stop cleanly",description:"If the screen is not the one expected, the run does not invent the next step."}]},stats:[{label:"Recording",value:"1",description:"The wallet flow, watched while it runs"},{label:"App",value:"E-wallet",description:"An existing mobile app, automated"},{label:"Proof",value:"On screen",description:"The session is in the recording"}],contentImages:[s,n],videos:[{src:"/proofs/ewallet-automation.webm",poster:"/proofs/posters/ewallet-automation.jpg",title:"The wallet, running without a finger on it",caption:"Remote view of the phone session while the script drives the e-wallet. Pause it anywhere. The screen you see is the step it was on."}]},{id:"4",slug:"auto-attendance",title:"Attendance that marks itself",client:"Client work",category:"Custom software",overview:"A recording of an attendance app on a phone, with a script finding the button and pressing it. Built so a check-in does not depend on someone remembering.",mainImage:"/proofs/posters/auto-attendance.jpg",heroImage:"/proofs/posters/auto-attendance.jpg",intro:"The phone is open on an attendance app. The log beside it shows the script finding the button and acting. This is a small piece of custom software with a clear job: the check-in happens.",challenge:"Attendance fails in a boring way. The app is there, the person is there, and the tap still gets missed. Doing it by reminder does not fix a process that has to happen every day.",solution:"The script opens the attendance app, finds the control, and completes the step. The recording is the client watching that happen once, on the real app, before they trust it to run on its own.",process:{timeline:"Recorded on the real app",steps:[{title:"Open the attendance app",description:"Same app the team already checks in with."},{title:"Find the control",description:"The script looks for the button on the current screen, and waits until it is there."},{title:"Mark it",description:"The tap happens in the app, not in a spreadsheet that pretends the app was opened."},{title:"Show the run",description:"The recording is what was handed over with the job."}]},stats:[{label:"Recording",value:"1",description:"The check-in, on the real app"},{label:"Job",value:"Daily",description:"A step that has to happen without a reminder"},{label:"Proof",value:"The tap",description:"You can see the app and the script together"}],contentImages:[s,o],videos:[{src:"/proofs/auto-attendance.webm",poster:"/proofs/posters/auto-attendance.jpg",title:"The attendance app, and the script beside it",caption:"The phone is on the left. The log on the right is the script finding the button. This is the run the client was shown."}]},{id:"5",slug:"web-submit",title:"A web job that files its own result",client:"Client work",category:"Custom software",overview:"A recording of a browser job that starts, runs, and leaves the result in a spreadsheet. One command, then the CSV.",mainImage:"/proofs/posters/10-1.jpg",heroImage:"/proofs/posters/10-1.jpg",intro:"The recording is short and specific. A command starts the job. The browser work runs. The result is a CSV sitting in the folder when it finishes. That is the delivery: not a dashboard mock, a file.",challenge:"Someone was repeating the same web steps and then copying the outcome into a sheet. The steps were knowable. The risk was a missed row, or a run that only lived in one person’s browser history.",solution:"The job starts from one command, does the web steps, and writes output.csv. The recording shows the command and the file. The client can run it again without asking someone to remember the sequence.",process:{timeline:"Recorded on delivery",steps:[{title:"One command",description:"The run starts from the project folder. No one clicks through a setup each time."},{title:"The web steps",description:"The job does the browser work that used to be done by hand."},{title:"A CSV at the end",description:"output.csv is the result. Open it. That is what the run produced."},{title:"Run it again",description:"The same command is the next day’s job."}]},stats:[{label:"Recording",value:"1",description:"Command, run, and the output file"},{label:"Result",value:"CSV",description:"A spreadsheet the client can open"},{label:"Start",value:"1 command",description:"No manual setup in the recording"}],contentImages:[n,o],videos:[{src:"/proofs/10-1.webm",poster:"/proofs/posters/10-1.jpg",title:"Start the job. The sheet is the result.",caption:"The command is on screen, and output.csv is the file it leaves behind. Play it. The work is the run, not a slide."}]},{id:"6",slug:"yum-data-collection",title:"Data collection that starts and stops itself",client:"Yum! Brands",category:"Phone scraping",overview:"An internal system at Yum! Brands. It collected public app and website data when a team asked, then shut the machines down. Shubham led the five developers who built it.",mainImage:s,heroImage:s,intro:"This was built inside Yum! Brands, where Shubham was a senior software developer. Teams needed fresh public data from apps and websites. They also needed the machines to go away when the job was done.",challenge:"The old loop was a person. Request the data, prepare a machine, run the collection, and remember to turn it off. Fresh data was slow, and idle machines were easy to leave running.",solution:"The system brought machines up for the collection, pulled from the app or website source, and shut them down when the run finished. Dashboards sat on top so the team could see the result. Shubham led five developers on it. The work was recognised internally because it gave people their hours back. The same boundary as the recordings above: public screens and public pages.",process:{timeline:"From 2020, at Yum! Brands",steps:[{title:"The manual loop",description:"Mapped who asked for data, how it was collected, and what was left running afterwards."},{title:"Start and stop",description:"Machines came up for the job and went away when the collection finished."},{title:"A dashboard",description:"The people who needed the data could see it, instead of waiting on a file."},{title:"Five developers",description:"Shubham led the team that built the tool."}]},stats:[{label:"Developers led",value:"5",description:"On this data system"},{label:"Role",value:"In-house",description:"Senior Software Developer at Yum! Brands"},{label:"Outcome",value:"Hours back",description:"Fresh data without someone babysitting the machines"}],contentImages:[o,n]},{id:"7",slug:"kvantum-dashboards",title:"Dashboards marketers could actually read",client:"Kvantum",category:"Custom software",overview:"Marketing dashboards at Kvantum, built so a large dataset still looked like a decision and not a spreadsheet. Kvantum was later acquired by Yum! Brands.",mainImage:o,heroImage:o,intro:"Shubham built this frontend as a software developer at Kvantum Marketing Insights. The people reading the screen were marketers. The dataset behind it was large. Kvantum was later acquired by Yum! Brands.",challenge:"Heavy data and a slow screen make a team stop trusting the number. If the view stalls, or the state is unclear, the dashboard is decoration.",solution:"A React frontend with Ant Design and Redux, built around rendering and transforming large sets so the screen stayed readable. No percentage lift is claimed. What shipped was a faster, clearer view of the same data the team already had.",process:{timeline:"September 2020 — April 2021",steps:[{title:"The decision on the screen",description:"Started from what the marketing team was trying to choose."},{title:"The frontend",description:"React, Ant Design, and Redux for a screen with a lot of state."},{title:"Large sets",description:"Rendering and data transformation so the UI held up."},{title:"Then Yum!",description:"Kvantum was acquired by Yum! Brands, and the product work continued there."}]},stats:[{label:"Role",value:"Builder",description:"Software Developer at Kvantum"},{label:"Stack",value:"React",description:"With Redux and Ant Design"},{label:"Later",value:"Yum!",description:"Kvantum was acquired by Yum! Brands"}],contentImages:[s,n]},{id:"8",slug:"yum-enterprise-web",title:"Screens that still work past a million records",client:"Yum! Brands",category:"Custom software",overview:"Enterprise web apps, server-driven UI, and live dashboards at Yum! Brands, including tools built to stay usable past a million records.",mainImage:n,heroImage:n,intro:"Alongside the data platform, the work at Yum! Brands was the software teams opened every day. Server-driven screens, live dashboards, and applications that had to keep up with the size of the data.",challenge:"Internal tools look fine on a sample. They stall when the table has a million rows, or when the layout has to change without shipping a whole new app.",solution:"High-performance frontends, including server-driven UI so a screen could change with the product, and dashboards meant to be used while the operation was live. Applications in this work were built to manage a million-plus records. Where a data-science result needed a person to act on it, it was put on the screen. A revenue number is not claimed. The scale and the screens are the work.",process:{timeline:"From September 2020, at Yum! Brands",steps:[{title:"The decision",description:"Started from what the person on the screen had to do."},{title:"Server-driven UI",description:"Layouts that could move without a fresh release for every change."},{title:"A million records",description:"Interfaces kept usable as the data grew past that line."},{title:"Model output, on the product",description:"A data-science result was only useful once a person could act on it."}]},stats:[{label:"Records",value:"1M+",description:"Scale the data-heavy applications were built to manage"},{label:"UI",value:"SDUI",description:"Server-driven screens"},{label:"Role",value:"Senior",description:"Senior Software Developer at Yum! Brands"}],contentImages:[s,o]}]}}]);